package com.project7.localmanager;
import java.io.*;import java.util.*;
final class MultiWishState {
 static final String META="q7WishGroupScope",POLICY="wish-group-first-acquisition-v1";
 static final class Group {int count;final Set<Integer>finished=new LinkedHashSet<>(),animated=new LinkedHashSet<>();byte[]raw=BsonLite.EMPTY_DOCUMENT;}
 final MultiWishSpec spec;final Map<Integer,Group>groups=new TreeMap<>();final List<byte[]>opaque=new ArrayList<>();
 private MultiWishState(MultiWishSpec s){spec=s;}
 static MultiWishState read(MultiWishSpec spec,byte[]state,byte[]profile,boolean coordinate)throws Exception{MultiWishState s=new MultiWishState(spec);byte[]meta=BsonLite.documentValue(state,META);WishCatalog.need(!BsonLite.keys(state).contains(META)||meta!=null,"wish group metadata type");if(meta!=null)WishCatalog.need(Integer.valueOf(1).equals(BsonLite.intValue(meta,"v"))&&WishCatalog.SHA256.equals(BsonLite.stringValue(meta,"hash"))&&POLICY.equals(BsonLite.stringValue(meta,"policy"))&&Integer.valueOf(spec.epoch).equals(BsonLite.intValue(meta,"epoch")),"wish group scope");byte[]pairs=BsonLite.arrayValue(state,"wi");WishCatalog.need(!BsonLite.keys(state).contains("wi")||pairs!=null,"wi type");if(pairs!=null)for(byte[]p:LocalResourceEngine.array(pairs)){Integer gid=BsonLite.intValue(p,"0");WishCatalog.need(gid!=null,"wi gid");if(!spec.groups.containsKey(gid)){s.opaque.add(p);continue;}WishCatalog.need(!s.groups.containsKey(gid),"duplicate wi");byte[]d=BsonLite.documentValue(p,"1");WishCatalog.need(d!=null,"wi group");Group g=new Group();g.raw=d;WishCatalog.need(!BsonLite.keys(d).contains("c")||BsonLite.intValue(d,"c")!=null,"wi count type");g.count=WishChoosePolicy.value(d,"c",0);WishCatalog.need(g.count>=0,"wi count");List<Integer>f=BsonLite.intArrayValues(d,"f"),a=BsonLite.intArrayValues(d,"a");WishCatalog.need(!BsonLite.keys(d).contains("f")||f!=null&&BsonLite.arrayValue(d,"f")!=null&&f.size()==BsonLite.keys(BsonLite.arrayValue(d,"f")).size(),"wi f type");WishCatalog.need(!BsonLite.keys(d).contains("a")||a!=null&&BsonLite.arrayValue(d,"a")!=null&&a.size()==BsonLite.keys(BsonLite.arrayValue(d,"a")).size(),"wi a type");if(f!=null)g.finished.addAll(f);if(a!=null)g.animated.addAll(a);WishCatalog.need(spec.rowIds(gid).containsAll(g.finished)&&g.finished.containsAll(g.animated),"wi finished/animation domain");s.groups.put(gid,g);}
  for(int gid:spec.groups.keySet()){Group g=s.groups.computeIfAbsent(gid,k->new Group());if(coordinate)for(Map<?,?>row:spec.groups.get(gid)){int id=DynamicCatalog.num(row.get("id"));if(LocalResourceEngine.ownsHero(profile,DynamicCatalog.num(row.get("wish_target")))&&g.finished.add(id))g.animated.add(id);}if(coordinate&&g.finished.containsAll(spec.rowIds(gid)))g.count=0;}
  return s;
 }
 void after(byte[]profile)throws Exception{for(Map.Entry<Integer,List<Map<?,?>>>e:spec.groups.entrySet()){Group g=groups.get(e.getKey());boolean hit=false;for(Map<?,?>r:e.getValue()){int id=DynamicCatalog.num(r.get("id"));if(LocalResourceEngine.ownsHero(profile,DynamicCatalog.num(r.get("wish_target")))&&g.finished.add(id))hit=true;}if(hit||g.finished.containsAll(spec.rowIds(e.getKey())))g.count=0;else g.count=Math.addExact(g.count,1);}}
 List<List<Object>>pairs(){List<List<Object>>pairs=new ArrayList<>();for(byte[]p:opaque)pairs.add(Arrays.<Object>asList(BsonLite.intValue(p,"0"),BsonLite.documentValue(p,"1")));for(Map.Entry<Integer,Group>e:groups.entrySet()){Group g=e.getValue();byte[]d=BsonLite.withProfileInt(g.raw,"c",g.count);d=BsonLite.withProfileArray(d,"f",new ArrayList<>(g.finished));d=BsonLite.withProfileArray(d,"a",new ArrayList<>(g.animated));pairs.add(Arrays.<Object>asList(e.getKey(),d));}return pairs;}
 byte[]save(byte[]state){state=BsonLite.withProfileArray(state,"wi",pairs());return BsonLite.withProfileDocument(state,META,BsonLite.document("v",1,"hash",WishCatalog.SHA256,"policy",POLICY,"epoch",spec.epoch));}
}
